/**
 * #27 safe scaffold: SRT/VTT import + export, autoGenerated cues, Generate-subtitles UI
 * behind a swappable Transcriber, no-speech / error / timeout states, and a guard that
 * fails on ANY outbound request (no cloud STT, no model download).
 */
import { test, expect, Page } from '@playwright/test';
import fs from 'fs';
import path from 'path';
import { fileURLToPath } from 'url';
import { isSilent, cleanWhisperSegments } from '../utils/whisperTranscriber';
import { mapSourceSegmentsToTimeline, fitCuesAroundManual, segmentsToCues, replaceAutoSubtitles, MIN_FITTED_CUE_SECONDS } from '../utils/subtitleGeneration';
import { groupWordsIntoSegments } from '../utils/whisperWords';
import { parseSrt, parseVtt, toSrt, toVtt, parseSubtitleFile, formatCueTime, parseCueTime } from '../utils/subtitleFormats';

const __dirname = path.dirname(fileURLToPath(import.meta.url));
const FIXTURE = path.join(__dirname, 'fixtures', 'e2e-black-60s.webm'); // video only, no audio track
const FIXTURE_SILENT = path.join(__dirname, 'fixtures', 'e2e-silent-audio-5s.webm'); // silent opus track
const FIXTURE_TONE = path.join(__dirname, 'fixtures', 'e2e-tone-audio-5s.webm'); // audible 440 Hz track (passes the pre-prompt speech check)
const FIXTURE_LONG = path.join(__dirname, 'fixtures', 'e2e-black-11min.webm'); // 660 s, over the 10-min web limit
let workers: string[] = [];

let unexpected: string[] = [];

/**
 * Pre-existing app-shell assets from index.html on main (Tailwind CDN + Inter font), loaded
 * before any #27 code runs. Exact hosts only; nothing else is allowed.
 */
const SHELL_HOSTS = new Set(['cdn.tailwindcss.com', 'fonts.googleapis.com', 'fonts.gstatic.com']);

/** Every other request must be same-origin (dev server), blob: or data:. Anything else fails the test. */
async function guardNetwork(page: Page, baseURL: string) {
  unexpected = [];
  const origin = new URL(baseURL).origin;
  const ok = (u: string) => u.startsWith(origin) || u.startsWith('blob:') || u.startsWith('data:')
    || (u.startsWith('https://') && SHELL_HOSTS.has(new URL(u).hostname));
  page.on('request', r => { if (!ok(r.url())) unexpected.push(r.url()); });
  workers = [];
  page.on('worker', w => { workers.push(w.url()); if (!ok(w.url())) unexpected.push(`worker:${w.url()}`); });
  await page.context().route('**/*', route => {
    const u = route.request().url();
    if (ok(u)) return route.continue();
    unexpected.push(u);
    return route.abort();
  });
}

const MODELISH = /\.(onnx|bin|gguf|ggml|tflite|safetensors)(\?|$)|huggingface|whisper|transformers/i;

async function setup(page: Page, baseURL: string, fixture = FIXTURE, durationHint = 60) {
  await guardNetwork(page, baseURL);
  await page.addInitScript(() => {
    (window as any).__FRAMECUT_E2E_ENABLED__ = true;
    try { localStorage.removeItem('framecut-project-v1'); } catch {}
  });
  await page.goto('/');
  await page.waitForFunction(() => !!(window as any).__FRAMECUT_E2E__);
  const b64 = fs.readFileSync(fixture).toString('base64');
  await page.evaluate(async ({ b64, durationHint }) => {
    const bin = atob(b64); const bytes = new Uint8Array(bin.length);
    for (let i = 0; i < bin.length; i++) bytes[i] = bin.charCodeAt(i);
    await (window as any).__FRAMECUT_E2E__.loadWithEvents(new Blob([bytes], { type: 'video/webm' }), [], durationHint);
  }, { b64, durationHint });
  await page.waitForFunction(() => { const s = (window as any).__FRAMECUT_E2E__?.getSnapshot?.(); return s && s.hasMainVideo && s.duration > 0; }, null, { timeout: 20000 });
}

const subs = (page: Page) => page.evaluate(() => (window as any).__FRAMECUT_E2E__.getSnapshot().subtitles as { id: string; start: number; end: number; text: string; autoGenerated: boolean }[]);

/** Inject an in-page mock transcriber. `script` is the body of transcribe(req, signal) returning segments. */
async function injectMock(page: Page, script: string) {
  await page.evaluate((script) => {
    const fn = new Function('req', 'signal', script) as any;
    (window as any).__FRAMECUT_E2E__.setTranscriber({ id: 'mock', availability: () => ({ available: true }), transcribe: async (req: any, signal: any) => fn(req, signal) });
  }, script);
}

const generateBtn = (page: Page) => page.getByRole('button', { name: 'Generate subtitles' });
const status = (page: Page) => page.getByTestId('subtitle-status');

test.afterEach(async () => {
  expect(unexpected, 'unexpected outbound requests').toEqual([]);
});

test.describe('#27 SRT/VTT formats (pure)', () => {
  const cues = [
    { start: 0, end: 1.5, text: 'Hello world' },
    { start: 2.001, end: 4.999, text: 'Two lines\nsecond <b>line</b> & more' },
    { start: 3725.042, end: 3726, text: 'Over an hour --> still fine' },
  ];

  test('SRT round-trip is lossless', () => {
    expect(parseSrt(toSrt(cues))).toEqual(cues);
  });
  test('VTT round-trip is lossless (incl. escaping)', () => {
    const vtt = toVtt(cues);
    expect(vtt.startsWith('WEBVTT\n')).toBe(true);
    expect(vtt).toContain('&lt;b&gt;');
    expect(parseVtt(vtt)).toEqual(cues);
  });
  test('SRT -> VTT -> SRT keeps text and ms timing', () => {
    expect(parseSrt(toSrt(parseVtt(toVtt(parseSrt(toSrt(cues))))))).toEqual(cues);
  });
  test('parses CRLF, BOM, VTT short timestamps, NOTE blocks, cue ids; rejects junk', () => {
    const vtt = '\uFEFFWEBVTT\r\n\r\nNOTE hi\r\n\r\nintro\r\n00:01.250 --> 00:02.000 align:start\r\nA\r\n';
    expect(parseVtt(vtt)).toEqual([{ start: 1.25, end: 2, text: 'A' }]);
    expect(parseCueTime('01:02:03,004')).toBeCloseTo(3723.004, 6);
    expect(formatCueTime(3723.004, ',')).toBe('01:02:03,004');
    expect(() => parseSubtitleFile('not subtitles', 'x.srt')).toThrow(/No subtitle cues/);
    expect(parseSrt('1\n00:00:02,000 --> 00:00:01,000\nbackwards\n')).toEqual([]);
  });
});

async function injectWhisperWithCountingWorker(page: Page) {
  await page.evaluate(() => {
    const w = window as any; w.__workerRuns = 0;
    const E = w.__FRAMECUT_E2E__;
    // Real audio decoding + silence detection; the worker must never be reached.
    E.setTranscriber(E.createWhisperTranscriber({
      makeWorker: () => { w.__workerRuns++; return new Worker(URL.createObjectURL(new Blob(['self.onmessage=(e)=>self.postMessage({type:"result",id:e.data.id,segments:[{start:0,end:1,text:"hallucination"}]})'], { type: 'text/javascript' }))); },
      isReady: async () => true,
    }));
  });
}

test.describe('#27 no audio / silence / over limit', () => {
  test('video with NO audio track → "No speech found", nothing generated, engine never run', async ({ page, baseURL }) => {
    await setup(page, baseURL!, FIXTURE, 60);
    await injectWhisperWithCountingWorker(page);
    await generateBtn(page).click();
    await expect(status(page)).toHaveAttribute('data-kind', 'empty');
    await expect(status(page)).toContainText('No speech found');
    expect(await subs(page)).toEqual([]);
    expect(await page.evaluate(() => (window as any).__workerRuns)).toBe(0);
    await expect(generateBtn(page)).toBeEnabled();
  });

  test('video with a SILENT audio track → "No speech found", engine never run', async ({ page, baseURL }) => {
    await setup(page, baseURL!, FIXTURE_SILENT, 5);
    await injectWhisperWithCountingWorker(page);
    await generateBtn(page).click();
    await expect(status(page)).toHaveAttribute('data-kind', 'empty');
    expect(await subs(page)).toEqual([]);
    expect(await page.evaluate(() => (window as any).__workerRuns)).toBe(0);
  });

  test('over the 10-minute web limit → macOS app suggestion, no prompt, nothing generated', async ({ page, baseURL }) => {
    await setup(page, baseURL!, FIXTURE_LONG, 660);
    expect(await page.evaluate(() => (window as any).__FRAMECUT_E2E__.getSnapshot().duration)).toBeGreaterThan(600);
    await generateBtn(page).click(); // real default engine
    await expect(status(page)).toHaveAttribute('data-kind', 'over-limit');
    await expect(status(page)).toContainText('up to 10 minutes');
    await expect(page.getByTestId('subtitle-macos-app-link')).toHaveAttribute('href', '/download/mac');
    await expect(page.getByRole('button', { name: 'Download model and generate subtitles' })).toHaveCount(0);
    await page.waitForTimeout(500);
    expect(await subs(page)).toEqual([]);
    expect(workers.filter(u => /whisper/i.test(u))).toEqual([]);
  });
});

test.describe('#27 transcription helpers (pure)', () => {
  test('silence detection, non-speech markers, source→timeline mapping through trims', () => {
    expect(isSilent(new Float32Array(16000))).toBe(true);
    const loud = new Float32Array(16000); loud[8000] = 0.9; loud.fill(0.2, 4000, 5000);
    expect(isSilent(loud)).toBe(false);
    expect(cleanWhisperSegments([{ start: 0, end: 1, text: ' [BLANK_AUDIO] ' }, { start: 1, end: 2, text: '(music) Hi  there' }])).toEqual([{ start: 1, end: 2, text: 'Hi there' }]);
    const clips: any[] = [
      { id: 'a', mediaType: 'main', offset: 0, sourceStart: 0, sourceEnd: 10, speed: 1 },
      { id: 'b', mediaType: 'main', offset: 10, sourceStart: 20, sourceEnd: 30, speed: 2 },
    ];
    expect(mapSourceSegmentsToTimeline([{ start: 2, end: 4, text: 'kept' }, { start: 12, end: 15, text: 'cut' }, { start: 22, end: 26, text: 'fast' }], clips))
      .toEqual([{ start: 2, end: 4, text: 'kept' }, { start: 11, end: 13, text: 'fast' }]);
  });
});

test.describe('#27 subtitle tools in the editor', () => {
  test.beforeEach(async ({ page, baseURL }) => { await setup(page, baseURL!); });

  test('default engine: opt-in size warning before ANY download; "Not now" downloads nothing', async ({ page, baseURL }) => {
    await setup(page, baseURL!, FIXTURE_TONE, 5); // needs real audio: silent/no-audio media now short-circuit before the prompt
    await expect(generateBtn(page)).toHaveAttribute('data-available', 'true');
    await generateBtn(page).click();
    await expect(status(page)).toHaveAttribute('data-kind', 'confirm-download');
    await expect(status(page)).toContainText('speech model (about 55 MB)');
    await expect(status(page)).toContainText('cached in your browser');
    await expect(status(page)).toContainText('English is officially supported');
    await expect(page.getByRole('button', { name: 'Download model and generate subtitles' })).toBeVisible();
    await page.getByRole('button', { name: 'Not now' }).click();
    await expect(status(page)).toHaveCount(0);
    await page.waitForTimeout(500);
    expect(await subs(page)).toEqual([]);
    expect(workers.filter(u => /whisper/i.test(u))).toEqual([]);
    expect(unexpected.filter(u => MODELISH.test(u))).toEqual([]);
  });

  test('opt-in flow (mocked model): confirm → download progress → cues; cached model is not prompted again', async ({ page }) => {
    await page.evaluate(() => {
      const w = window as any; w.__cached = false; w.__workerRuns = 0;
      const src = `self.onmessage = (e) => { const m = e.data; if (m.type !== 'transcribe') return;
        self.postMessage({ type: 'progress', id: m.id, phase: 'download', progress: 0.5 });
        self.postMessage({ type: 'progress', id: m.id, phase: 'transcribe', progress: 0 });
        setTimeout(() => self.postMessage({ type: 'result', id: m.id, segments: [
          { start: 1, end: 3, text: ' Hello there. ' }, { start: 3, end: 4, text: '[BLANK_AUDIO]' }, { start: 5, end: 7, text: 'pcm=' + m.request.audio.length } ] }), 300); };`;
      const E = w.__FRAMECUT_E2E__;
      E.setTranscriber(E.createWhisperTranscriber({
        makeWorker: () => { w.__workerRuns++; return new Worker(URL.createObjectURL(new Blob([src], { type: 'text/javascript' }))); },
        isReady: async () => w.__cached,
        decodeAudio: async () => { const a = new Float32Array(16000); for (let i = 0; i < a.length; i++) a[i] = Math.sin(i / 5) * 0.3; return a; },
      }));
    });
    await generateBtn(page).click();
    await expect(status(page)).toHaveAttribute('data-kind', 'confirm-download');
    expect(await page.evaluate(() => (window as any).__workerRuns)).toBe(0); // nothing before consent
    await page.getByRole('button', { name: 'Download model and generate subtitles' }).click();
    await expect(status(page)).toHaveAttribute('data-kind', 'done');
    await expect(status(page)).toContainText('English is officially supported');
    expect((await subs(page)).map(x => [x.start, x.end, x.text])).toEqual([[1, 3, 'Hello there.'], [5, 7, 'pcm=16000']]);

    await page.evaluate(() => { (window as any).__cached = true; });
    await generateBtn(page).click();
    await expect(status(page)).toHaveAttribute('data-kind', 'running'); // no prompt once cached
    await expect(status(page)).toHaveAttribute('data-kind', 'done');
    expect(await page.evaluate(() => (window as any).__workerRuns)).toBe(2);
  });

  test('generate with mock: auto cues; regenerate replaces only auto; edited + manual kept; undo works', async ({ page }) => {
    await page.getByTitle('Add Subtitle').click(); // manual cue at t=0..3
    await injectMock(page, `return [{start:5,end:7,text:' one '},{start:8,end:9,text:'two'},{start:10,end:12,text:'three'},{start:13,end:13,text:'zero-length'},{start:14,end:15,text:'   '}];`);
    await generateBtn(page).click();
    await expect(status(page)).toHaveAttribute('data-kind', 'done');
    let s = await subs(page);
    expect(s.filter(x => !x.autoGenerated).map(x => x.text)).toEqual(['New Subtitle']);
    expect(s.filter(x => x.autoGenerated).map(x => [x.start, x.end, x.text])).toEqual([[5, 7, 'one'], [8, 9, 'two'], [10, 12, 'three']]);

    // Editing a generated cue claims it (no longer auto).
    const two = s.find(x => x.text === 'two')!;
    await page.evaluate((id) => (window as any).__FRAMECUT_E2E__.updateSubtitle(id, { text: 'two (edited)' }), two.id);
    await expect.poll(async () => (await subs(page)).find(x => x.id === two.id)!.autoGenerated).toBe(false);

    await injectMock(page, `return [{start:20,end:22,text:'fresh'}];`);
    await generateBtn(page).click();
    await expect(status(page)).toContainText('Generated 1 subtitle');
    s = await subs(page);
    expect(s.map(x => x.text).sort()).toEqual(['New Subtitle', 'fresh', 'two (edited)']);
    expect(s.filter(x => x.autoGenerated).map(x => x.text)).toEqual(['fresh']);

    // Undo the regenerate → previous auto cues return, edit intact.
    await page.evaluate(() => (window as any).__FRAMECUT_E2E__.undo());
    await expect.poll(async () => (await subs(page)).map(x => x.text).sort()).toEqual(['New Subtitle', 'one', 'three', 'two (edited)']);
    // Undo edit, then undo generate → only manual cue.
    await page.evaluate(() => (window as any).__FRAMECUT_E2E__.undo());
    await expect.poll(async () => (await subs(page)).find(x => x.id === two.id)?.text).toBe('two');
    await page.evaluate(() => (window as any).__FRAMECUT_E2E__.undo());
    await expect.poll(async () => (await subs(page)).map(x => x.text)).toEqual(['New Subtitle']);
    // Redo restores generated cues.
    await page.evaluate(() => (window as any).__FRAMECUT_E2E__.redo());
    await expect.poll(async () => (await subs(page)).filter(x => x.autoGenerated).length).toBe(3);
  });

  test('worker plumbing: mock worker returns cues; shipped stub worker errors cleanly', async ({ page }) => {
    await page.evaluate(() => {
      const src = `self.onmessage = (e) => { const m = e.data; if (m.type !== 'transcribe') return;
        self.postMessage({ type: 'progress', id: m.id, progress: 0.5 });
        self.postMessage({ type: 'result', id: m.id, segments: [{ start: 1, end: 2, text: 'from worker dur=' + Math.round(m.request.duration) }] }); };`;
      const E = (window as any).__FRAMECUT_E2E__;
      E.setTranscriber(E.createWorkerTranscriber(() => new Worker(URL.createObjectURL(new Blob([src], { type: 'text/javascript' })))));
    });
    await generateBtn(page).click();
    await expect(status(page)).toHaveAttribute('data-kind', 'done');
    expect((await subs(page)).map(x => [x.text, x.autoGenerated])).toEqual([['from worker dur=60', true]]);

    await page.evaluate(() => { const E = (window as any).__FRAMECUT_E2E__; E.setTranscriber(E.createWorkerTranscriber(E.createStubWorker)); });
    await generateBtn(page).click();
    await expect(status(page)).toHaveAttribute('data-kind', 'error');
    await expect(status(page)).toContainText('No speech-to-text engine');
    await expect(generateBtn(page)).toBeEnabled();
    await expect(page.locator('[aria-label="Generate subtitles"] .animate-spin')).toHaveCount(0);
    expect((await subs(page)).length).toBe(1);
  });

  test('no speech: friendly message, subtitles unchanged, no history entry', async ({ page }) => {
    await page.getByTitle('Add Subtitle').click();
    await injectMock(page, `return [];`);
    await generateBtn(page).click();
    await expect(status(page)).toHaveAttribute('data-kind', 'empty');
    await expect(status(page)).toContainText('No speech found');
    expect((await subs(page)).map(x => x.text)).toEqual(['New Subtitle']);
    await page.evaluate(() => (window as any).__FRAMECUT_E2E__.undo()); // undoes Add Subtitle, not a no-op generate
    await expect.poll(() => subs(page)).toEqual([]);
  });

  test('errors, crashes, timeouts and cancel never leave a stuck spinner', async ({ page }) => {
    await injectMock(page, `throw new Error('engine exploded');`);
    await generateBtn(page).click();
    await expect(status(page)).toContainText('engine exploded');
    await expect(generateBtn(page)).toBeEnabled();

    // Worker that crashes.
    await page.evaluate(() => { const E = (window as any).__FRAMECUT_E2E__;
      E.setTranscriber(E.createWorkerTranscriber(() => new Worker(URL.createObjectURL(new Blob(['self.onmessage = () => { throw new Error("boom"); };'], { type: 'text/javascript' }))))); });
    await generateBtn(page).click();
    await expect(status(page)).toHaveAttribute('data-kind', 'error');
    await expect(generateBtn(page)).toBeEnabled();

    // Hanging engine hits the timeout.
    await page.evaluate(() => (window as any).__FRAMECUT_E2E__.setSubtitleGenerationTimeoutMs(800));
    await injectMock(page, `return new Promise(() => {});`);
    await generateBtn(page).click();
    await expect(status(page)).toHaveAttribute('data-kind', 'running');
    await expect(generateBtn(page)).toBeDisabled();
    await expect(status(page)).toContainText('timed out', { timeout: 5000 });
    await expect(generateBtn(page)).toBeEnabled();

    // Cancel while running; a late result must not be applied.
    await page.evaluate(() => (window as any).__FRAMECUT_E2E__.setSubtitleGenerationTimeoutMs(60000));
    await injectMock(page, `return new Promise(r => setTimeout(() => r([{start:1,end:2,text:'late'}]), 700));`);
    await generateBtn(page).click();
    await page.getByRole('button', { name: 'Cancel subtitle generation' }).click();
    await expect(status(page)).toHaveCount(0);
    await expect(generateBtn(page)).toBeEnabled();
    await page.waitForTimeout(1200);
    expect(await subs(page)).toEqual([]);
    await expect(status(page)).toHaveCount(0);
  });

  test('import SRT + VTT as manual cues, export both, exported files round-trip', async ({ page }, testInfo) => {
    const srt = '1\n00:00:01,250 --> 00:00:03,500\nHello\nthere\n\n2\n00:00:04,000 --> 00:00:05,001\nA & <b>B</b>\n';
    await page.getByTestId('subtitle-import-input').setInputFiles({ name: 'in.srt', mimeType: 'application/x-subrip', buffer: Buffer.from(srt) });
    await expect(status(page)).toContainText('Imported 2 subtitles from in.srt');
    let s = await subs(page);
    expect(s.map(x => [x.start, x.end, x.text, x.autoGenerated])).toEqual([[1.25, 3.5, 'Hello\nthere', false], [4, 5.001, 'A & <b>B</b>', false]]);

    // Imported cues survive regenerate.
    await injectMock(page, `return [{start:10,end:11,text:'auto'}];`);
    await generateBtn(page).click();
    await expect(status(page)).toHaveAttribute('data-kind', 'done');
    await injectMock(page, `return [{start:12,end:13,text:'auto2'}];`);
    await generateBtn(page).click();
    await expect(status(page)).toHaveAttribute('data-kind', 'done');
    s = await subs(page);
    expect(s.map(x => x.text)).toEqual(['Hello\nthere', 'A & <b>B</b>', 'auto2']);
    const expected = s.map(x => ({ start: x.start, end: x.end, text: x.text }));

    for (const fmt of ['srt', 'vtt'] as const) {
      const [dl] = await Promise.all([page.waitForEvent('download'), page.getByRole('button', { name: `Export subtitles as ${fmt.toUpperCase()}` }).click()]);
      expect(dl.suggestedFilename()).toMatch(new RegExp(`\\.${fmt}$`));
      const file = testInfo.outputPath(`out.${fmt}`);
      await dl.saveAs(file);
      const text = fs.readFileSync(file, 'utf8');
      expect(parseSubtitleFile(text, file)).toEqual(expected);
      await expect(status(page)).toContainText(`as .${fmt}`);
    }

    // Re-import the exported VTT through the UI: same cues appended (now 6).
    const vttPath = testInfo.outputPath('out.vtt');
    await page.getByTestId('subtitle-import-input').setInputFiles(vttPath);
    await expect(status(page)).toContainText('Imported 3 subtitles from out.vtt');
    s = await subs(page);
    expect(s.slice(3).map(x => ({ start: x.start, end: x.end, text: x.text }))).toEqual(expected);

    // Undo the import.
    await page.evaluate(() => (window as any).__FRAMECUT_E2E__.undo());
    await expect.poll(async () => (await subs(page)).length).toBe(3);
  });

  test('bad import file shows an error and changes nothing', async ({ page }) => {
    await page.getByTestId('subtitle-import-input').setInputFiles({ name: 'bad.srt', mimeType: 'text/plain', buffer: Buffer.from('hello') });
    await expect(status(page)).toHaveAttribute('data-kind', 'error');
    await expect(status(page)).toContainText("Couldn't import bad.srt");
    expect(await subs(page)).toEqual([]);
    await expect(page.getByRole('button', { name: 'Export subtitles as SRT' })).toBeDisabled();
  });
});

test.describe('#27 QA fixes: retime claims a cue; speech check before prompt', () => {
  const cueBox = (page: Page, text: string) => page.locator('div.absolute.group', { has: page.locator('span.truncate', { hasText: new RegExp(`^${text}$`) }) });

  async function dragBy(page: Page, x: number, y: number, dx: number) {
    await page.mouse.move(x, y);
    await page.mouse.down();
    for (let i = 1; i <= 6; i++) await page.mouse.move(x + (dx * i) / 6, y);
    await page.mouse.up();
  }

  for (const mode of ['move', 'trim-left', 'trim-right'] as const) {
    test(`${mode} of a generated cue via real mouse makes it manual and it survives regenerate`, async ({ page, baseURL }) => {
      await setup(page, baseURL!, FIXTURE, 60);
      await injectMock(page, `return [{start:2,end:5,text:'GENA'},{start:8,end:12,text:'GENB'},{start:15,end:18,text:'GENC'}];`);
      await generateBtn(page).click();
      await expect(status(page)).toHaveAttribute('data-kind', 'done');
      const before = (await subs(page)).find(x => x.text === 'GENB')!;
      const box = cueBox(page, 'GENB');
      await box.scrollIntoViewIfNeeded();
      let b = (await box.boundingBox())!;
      if (mode !== 'move') { await box.click({ position: { x: b.width / 2, y: b.height / 2 } }); b = (await box.boundingBox())!; }
      const y = b.y + b.height / 2;
      const x = mode === 'move' ? b.x + b.width / 2 : mode === 'trim-left' ? b.x + 3 : b.x + b.width - 3;
      await dragBy(page, x, y, mode === 'trim-left' ? 20 : mode === 'trim-right' ? -20 : 30);
      await expect.poll(async () => {
        const c = (await subs(page)).find(s => s.id === before.id)!;
        return c.start !== before.start || c.end !== before.end;
      }).toBe(true);
      await expect.poll(async () => (await subs(page)).find(s => s.id === before.id)!.autoGenerated).toBe(false);
      await injectMock(page, `return [{start:30,end:32,text:'fresh'}];`);
      await generateBtn(page).click();
      await expect(status(page)).toContainText('Generated 1 subtitle');
      const after = await subs(page);
      expect(after.find(s => s.id === before.id)?.autoGenerated).toBe(false);
      expect(after.map(s => s.text).sort()).toEqual(['GENB', 'fresh']);
    });
  }

  test('fresh browser (model NOT cached) + silent audio → "No speech found" with no download prompt', async ({ page, baseURL }) => {
    await setup(page, baseURL!, FIXTURE_SILENT, 5);
    await page.evaluate(() => {
      const w = window as any; w.__workerRuns = 0;
      const E = w.__FRAMECUT_E2E__;
      E.setTranscriber(E.createWhisperTranscriber({
        makeWorker: () => { w.__workerRuns++; throw new Error('worker must not start'); },
        isReady: async () => false, // fresh browser: the prompt WOULD show if reached
      }));
    });
    await generateBtn(page).click();
    await expect(status(page)).toHaveAttribute('data-kind', 'empty');
    await expect(status(page)).toContainText('No speech found');
    await expect(page.getByRole('button', { name: 'Download model and generate subtitles' })).toHaveCount(0);
    expect(await subs(page)).toEqual([]);
    expect(await page.evaluate(() => (window as any).__workerRuns)).toBe(0);
  });
});

test.describe('#27 QA warns: no overlap with manual cues; Checking-audio guard', () => {
  test('fitCuesAroundManual trims to the longest free part or drops (pure)', () => {
    const manual = [{ start: 2, end: 4 }, { start: 10, end: 12 }];
    expect(fitCuesAroundManual([
      { start: 0, end: 1, text: 'clear' },
      { start: 1, end: 3, text: 'tail-hit' },
      { start: 3, end: 7, text: 'head-hit' },
      { start: 9, end: 13, text: 'straddle' },
      { start: 10.2, end: 11.8, text: 'inside' },
      { start: 3.9, end: 4.1, text: 'sliver' },
    ], manual)).toEqual([
      { start: 0, end: 1, text: 'clear' },
      { start: 1, end: 2, text: 'tail-hit' },
      { start: 4, end: 7, text: 'head-hit' },
      { start: 9, end: 10, text: 'straddle' },
    ]);
  });

  test('regenerate after a cue is claimed: new cues never overlap manual cues', async ({ page, baseURL }) => {
    await setup(page, baseURL!, FIXTURE, 60);
    await injectMock(page, `return [{start:2,end:5,text:'GENA'},{start:8,end:12,text:'GENB'}];`);
    await generateBtn(page).click();
    await expect(status(page)).toHaveAttribute('data-kind', 'done');
    const b = (await subs(page)).find(x => x.text === 'GENB')!;
    await page.evaluate((id) => (window as any).__FRAMECUT_E2E__.updateSubtitle(id, { start: 8.8, end: 12.8 }), b.id);
    await expect.poll(async () => (await subs(page)).find(x => x.id === b.id)!.autoGenerated).toBe(false);
    // Same transcript again: the new GENB (8–12) collides with the claimed one (8.8–12.8).
    await generateBtn(page).click();
    await expect(status(page)).toHaveAttribute('data-kind', 'done');
    const s = (await subs(page)).slice().sort((x, y) => x.start - y.start);
    for (let i = 0; i < s.length; i++) for (let j = i + 1; j < s.length; j++)
      expect(s[i].end <= s[j].start || s[j].end <= s[i].start, `${s[i].text} overlaps ${s[j].text}`).toBe(true);
    expect(s.find(x => x.id === b.id)).toMatchObject({ start: 8.8, end: 12.8, autoGenerated: false });
    expect(s.filter(x => x.autoGenerated).map(x => [x.text, x.start, x.end])).toEqual([['GENA', 2, 5], ['GENB', 8, 8.8]]);
  });

  async function slowCheckEngine(page: Page) {
    await page.evaluate(() => {
      const w = window as any; w.__checks = 0; w.__runs = 0; w.__releaseCheck = null;
      w.__FRAMECUT_E2E__.setTranscriber({
        id: 'slow-check', availability: () => ({ available: true }),
        hasSpeech: () => { w.__checks++; return new Promise<boolean>(r => { w.__releaseCheck = () => r(true); }); },
        transcribe: async () => { w.__runs++; return [{ start: 1, end: 2, text: 'ran' }]; },
      });
    });
  }

  test('double-click during "Checking audio…" starts only one run', async ({ page, baseURL }) => {
    await setup(page, baseURL!, FIXTURE, 60);
    await slowCheckEngine(page);
    await generateBtn(page).click();
    await expect(status(page)).toContainText('Checking audio');
    // The button is disabled while running; force a second start through the handler path too.
    await generateBtn(page).dispatchEvent('click');
    await generateBtn(page).dispatchEvent('click');
    await page.evaluate(() => (window as any).__releaseCheck());
    await expect(status(page)).toHaveAttribute('data-kind', 'done');
    expect(await page.evaluate(() => [(window as any).__checks, (window as any).__runs])).toEqual([1, 1]);
    expect((await subs(page)).map(x => x.text)).toEqual(['ran']);
  });

  test('Cancel during "Checking audio…" resets, generates nothing, and allows a fresh run', async ({ page, baseURL }) => {
    await setup(page, baseURL!, FIXTURE, 60);
    await slowCheckEngine(page);
    await generateBtn(page).click();
    await expect(status(page)).toContainText('Checking audio');
    await page.getByRole('button', { name: 'Cancel subtitle generation' }).click();
    await expect(status(page)).toHaveCount(0);
    await expect(generateBtn(page)).toBeEnabled();
    await page.evaluate(() => (window as any).__releaseCheck()); // late result from the cancelled check
    await page.waitForTimeout(300);
    expect(await page.evaluate(() => (window as any).__runs)).toBe(0);
    expect(await subs(page)).toEqual([]);
    await expect(status(page)).toHaveCount(0);
    // A new run works normally afterwards.
    await generateBtn(page).click();
    await page.evaluate(() => (window as any).__releaseCheck());
    await expect(status(page)).toHaveAttribute('data-kind', 'done');
    expect(await page.evaluate(() => (window as any).__runs)).toBe(1);
  });

  test('fresh browser + video with NO audio track → "No speech found", no download prompt', async ({ page, baseURL }) => {
    await setup(page, baseURL!, FIXTURE, 60);
    await page.evaluate(() => {
      const w = window as any; w.__workerRuns = 0;
      const E = w.__FRAMECUT_E2E__;
      E.setTranscriber(E.createWhisperTranscriber({ makeWorker: () => { w.__workerRuns++; throw new Error('no'); }, isReady: async () => false }));
    });
    await generateBtn(page).click();
    await expect(status(page)).toHaveAttribute('data-kind', 'empty');
    await expect(page.getByRole('button', { name: 'Download model and generate subtitles' })).toHaveCount(0);
    expect(await page.evaluate(() => (window as any).__workerRuns)).toBe(0);
  });
});

/** Real whisper-tiny q8 word output for the JFK sample (transformers.js 4.3.2, return_timestamps:'word'). */
const JFK_WORDS: { text: string; timestamp: [number, number] }[] = [
  [' And', 0.7, 1.08], [' so', 1.08, 1.34], [' my', 1.34, 1.7], [' fellow', 1.7, 2.3], [' Americans', 2.3, 3.76], [' ask', 3.76, 4.4],
  [' not', 4.4, 5.68], [' what', 5.68, 6], [' your', 6, 6.42], [' country', 6.42, 6.76], [' can', 6.76, 6.96], [' do', 6.96, 7.2],
  [' for', 7.2, 8.26], [' you,', 8.26, 8.28], [' ask', 8.62, 8.98], [' what', 8.98, 9.2], [' you', 9.2, 9.42], [' can', 9.42, 9.7],
  [' do', 9.7, 9.88], [' for', 9.88, 10.06], [' your', 10.06, 10.56], [' country.', 10.56, 11],
].map(([text, a, b]) => ({ text: text as string, timestamp: [a as number, b as number] }));

const W = (text: string, start: number, end: number) => ({ text, start, end });
const noOverlap = (cues: { start: number; end: number }[]) => {
  const s = [...cues].sort((a, b) => a.start - b.start);
  for (let i = 1; i < s.length; i++) if (s[i].start < s[i - 1].end - 1e-9) return false;
  return true;
};

test.describe('#27 fix round 3: word-accurate trims, cached-model status, no auto/auto overlap', () => {
  test('word timestamps group into subtitle-sized cues that keep their words (pure)', () => {
    const segs = groupWordsIntoSegments(JFK_WORDS as any, 11);
    expect(segs.every(s => s.end - s.start <= 7 && s.words!.length > 0)).toBe(true);
    expect(segs.map(s => s.text).join(' ')).toBe('And so my fellow Americans ask not what your country can do for you, ask what you can do for your country.');
    expect(segs[0].start).toBe(0.7);
    expect(segs[segs.length - 1].end).toBe(11);
    expect(noOverlap(segs)).toBe(true);
    // Missing / backwards ends and out-of-order words are repaired; blank words are dropped.
    const odd = groupWordsIntoSegments([{ text: ' b', timestamp: [1.5, 1] }, { text: ' a', timestamp: [1, null] }, { text: ' ', timestamp: [0, 1] }] as any, 5);
    expect(odd).toEqual([{ start: 1, end: 1.5, text: 'a b', words: [W(' a', 1, 1), W(' b', 1.5, 1.5)] }]);
  });

  test('(1) a cue trimmed around a manual cue keeps only the words in the kept time (pure)', () => {
    const [seg] = groupWordsIntoSegments(JFK_WORDS.slice(0, 5) as any, 11); // "And so my fellow Americans" 0.7–3.76
    const out = fitCuesAroundManual([seg], [{ start: 1.4, end: 10 }]);
    expect(out).toEqual([{ start: 0.7, end: 1.4, text: 'And so', words: [W(' And', 0.7, 1.08), W(' so', 1.08, 1.34)] }]);
    // Kept part long enough but with no word in it → dropped, never the whole sentence.
    expect(fitCuesAroundManual([{ start: 0, end: 4, text: 'late words', words: [W(' late', 2, 3), W(' words', 3, 4)] }], [{ start: 0.5, end: 4 }])).toEqual([]);
    // Real-run QA case: claimed cue 0.6–15, sliver 0–0.6 had the full JFK sentence; now no word sits there → dropped.
    const full = { start: 0, end: 11, text: 'whole sentence', words: JFK_WORDS.map(w => W(w.text, w.timestamp[0], w.timestamp[1])) };
    expect(fitCuesAroundManual([full], [{ start: 0.6, end: 15 }])).toEqual([]);
  });

  test('0.3 s boundary: exactly MIN_FITTED_CUE_SECONDS is kept, just under is dropped (pure)', () => {
    expect(MIN_FITTED_CUE_SECONDS).toBe(0.3);
    const m = [{ start: 1, end: 3 }];
    expect(fitCuesAroundManual([{ start: 0.7, end: 2, text: 'edge' }], m)).toEqual([{ start: 0.7, end: 1, text: 'edge' }]);
    expect(fitCuesAroundManual([{ start: 0.71, end: 2, text: 'under' }], m)).toEqual([]);
    expect(fitCuesAroundManual([{ start: 2.5, end: 3.3, text: 'after' }], m)).toEqual([{ start: 3, end: 3.3, text: 'after' }]);
    expect(fitCuesAroundManual([{ start: 2.5, end: 3.29, text: 'after-under' }], m)).toEqual([]);
    // With words: boundary piece kept only with a word in it.
    expect(fitCuesAroundManual([{ start: 0.7, end: 2, text: 'hi there', words: [W(' hi', 0.7, 0.95), W(' there', 1.2, 2)] }], m))
      .toEqual([{ start: 0.7, end: 1, text: 'hi', words: [W(' hi', 0.7, 0.95)] }]);
  });

  test('manual cue inside a generated range: longest side kept, with that side\'s words (pure)', () => {
    const words = [W(' one', 4, 4.8), W(' two', 5.1, 5.9), W(' three', 6.2, 7), W(' four', 7.1, 7.9)];
    expect(fitCuesAroundManual([{ start: 4, end: 8, text: 'one two three four', words }], [{ start: 5, end: 6 }]))
      .toEqual([{ start: 6, end: 8, text: 'three four', words: words.slice(2) }]);
    // Without word timings the time is trimmed and the text is kept (nothing finer to cut by).
    expect(fitCuesAroundManual([{ start: 4, end: 8, text: 'SPAN' }], [{ start: 5, end: 6 }])).toEqual([{ start: 6, end: 8, text: 'SPAN' }]);
  });

  test('(3) generated cues never overlap each other, whatever the engine returns (pure)', () => {
    // QA repro: SPAN 4–8 and ADJ 6–7 from the engine, manual 5–6 → previously SPAN' 6–8 and ADJ 6–7 overlapped.
    const cues = segmentsToCues([
      { start: 0.71, end: 3, text: 'U029' }, { start: 3, end: 3.31, text: 'O031' }, { start: 4, end: 8, text: 'SPAN' },
      { start: 6, end: 7, text: 'ADJ' }, { start: 9, end: 10, text: 'CLEAR' }, { start: 1.5, end: 2.5, text: 'INSIDE' },
    ], 60);
    expect(noOverlap(cues)).toBe(true);
    const subs = replaceAutoSubtitles([{ id: 'm1', start: 1, end: 3, text: 'MAN1' } as any, { id: 'm2', start: 5, end: 6, text: 'MAN2' } as any], cues);
    expect(noOverlap(subs)).toBe(true);
    expect(subs.filter(s => s.autoGenerated).map(s => [s.text, s.start, s.end])).toEqual([['O031', 3, 3.31], ['SPAN', 6, 8], ['CLEAR', 9, 10]]);
    // Whisper-style failures: a missing end stretched to the media end, stitched chunks repeating a range, words.
    const w = segmentsToCues([
      { start: 0, end: 30, text: 'a b', words: [W(' a', 0, 1), W(' b', 1, 2)] },
      { start: 3, end: 5, text: 'c', words: [W(' c', 3, 5)] },
      { start: 4, end: 6, text: 'c d', words: [W(' c', 4, 5), W(' d', 5, 6)] },
    ], 30);
    expect(noOverlap(w)).toBe(true);
    expect(w.map(c => [c.text, c.start, c.end])).toEqual([['a b', 0, 2], ['c', 3, 5], ['d', 5, 6]]);
    // Randomised: any engine output gives non-overlapping cues.
    let seed = 7; const rnd = () => (seed = (seed * 16807) % 2147483647) / 2147483647;
    for (let k = 0; k < 200; k++) {
      const segs = Array.from({ length: 8 }, (_, i) => { const a = rnd() * 20; const b = a + rnd() * 6; return { start: a, end: b, text: 'x' + i,
        words: rnd() < 0.5 ? undefined : [W(' p', a, (a + b) / 2), W(' q', (a + b) / 2, b)] }; });
      const c = segmentsToCues(segs, 20);
      expect(noOverlap(c)).toBe(true);
      expect(noOverlap(replaceAutoSubtitles([{ id: 'm', start: 5, end: 7, text: 'M' } as any], c))).toBe(true);
    }
  });

  test('(1) in the editor: regenerate around a claimed cue trims text with the words; undo restores', async ({ page, baseURL }) => {
    await setup(page, baseURL!, FIXTURE, 60);
    const js = JSON.stringify([{ start: 2, end: 6, text: 'alpha beta gamma delta', words: [W(' alpha', 2, 3), W(' beta', 3, 4), W(' gamma', 4, 5), W(' delta', 5, 6)] }]);
    await injectMock(page, `return ${js};`);
    await generateBtn(page).click();
    await expect(status(page)).toHaveAttribute('data-kind', 'done');
    const first = await subs(page);
    expect(first.map(x => [x.text, x.start, x.end])).toEqual([['alpha beta gamma delta', 2, 6]]);
    expect(Object.keys(first[0])).not.toContain('words');
    // Add a manual cue over the second half, then regenerate.
    await page.getByTestId('subtitle-import-input').setInputFiles({ name: 'm.srt', mimeType: 'text/plain', buffer: Buffer.from('1\n00:00:03,900 --> 00:00:08,000\nMANUAL\n') });
    await expect.poll(async () => (await subs(page)).length).toBe(2);
    const before = (await subs(page)).map(x => [x.text, x.start, x.end, x.autoGenerated]);
    await generateBtn(page).click();
    await expect(status(page)).toHaveAttribute('data-kind', 'done');
    const after = (await subs(page)).slice().sort((a, b) => a.start - b.start);
    expect(after.map(x => [x.text, x.start, x.end, x.autoGenerated])).toEqual([['alpha beta', 2, 3.9, true], ['MANUAL', 3.9, 8, false]]);
    expect(noOverlap(after)).toBe(true);
    // Undo the trimmed regenerate → exactly the state before it; redo → trimmed again.
    await page.evaluate(() => (window as any).__FRAMECUT_E2E__.undo());
    await expect.poll(async () => (await subs(page)).map(x => [x.text, x.start, x.end, x.autoGenerated])).toEqual(before);
    await page.evaluate(() => (window as any).__FRAMECUT_E2E__.redo());
    await expect.poll(async () => (await subs(page)).slice().sort((a, b) => a.start - b.start).map(x => [x.text, x.start, x.end])).toEqual([['alpha beta', 2, 3.9], ['MANUAL', 3.9, 8]]);
  });

  test('(3) in the editor: overlapping engine segments never produce overlapping cues', async ({ page, baseURL }) => {
    await setup(page, baseURL!, FIXTURE, 60);
    await injectMock(page, `return [{start:4,end:8,text:'SPAN'},{start:6,end:7,text:'ADJ'},{start:7.5,end:9,text:'TAIL'},{start:0,end:60,text:'STRETCHED'}];`);
    await generateBtn(page).click();
    await expect(status(page)).toHaveAttribute('data-kind', 'done');
    const s = await subs(page);
    expect(noOverlap(s)).toBe(true);
    expect(s.map(x => [x.text, x.start, x.end]).sort((a: any, b: any) => a[1] - b[1])).toEqual([['STRETCHED', 0, 60]]); // earliest-starting wins; the rest would overlap it
  });

  async function cachedModelEngine(page: Page, cached: boolean) {
    await page.evaluate((cached) => {
      const w = window as any; w.__statuses = [];
      const src = `self.onmessage = (e) => { const m = e.data; if (m.type !== 'transcribe') return;
        self.postMessage({ type: 'progress', id: m.id, phase: 'download', progress: 0.16 });
        setTimeout(() => { self.postMessage({ type: 'progress', id: m.id, phase: 'download', progress: 1 });
          self.postMessage({ type: 'progress', id: m.id, phase: 'transcribe', progress: 0 }); }, 400);
        setTimeout(() => self.postMessage({ type: 'result', id: m.id, segments: [{ start: 1, end: 2, text: 'hi' }] }), 800); };`;
      const E = w.__FRAMECUT_E2E__;
      E.setTranscriber(E.createWhisperTranscriber({
        makeWorker: () => new Worker(URL.createObjectURL(new Blob([src], { type: 'text/javascript' }))),
        isReady: async () => cached,
        decodeAudio: async () => { const a = new Float32Array(16000); for (let i = 0; i < a.length; i++) a[i] = Math.sin(i / 5) * 0.3; return a; },
      }));
      const obs = new MutationObserver(() => { const el = document.querySelector('[data-testid="subtitle-status"]'); if (el) w.__statuses.push(el.textContent); });
      obs.observe(document.body, { subtree: true, childList: true, characterData: true });
    }, cached);
  }

  test('(2) cached model: status says "Loading speech model…", never "Downloading… %"', async ({ page, baseURL }) => {
    await setup(page, baseURL!, FIXTURE, 60);
    await cachedModelEngine(page, true);
    await generateBtn(page).click();
    await expect(status(page)).toContainText('Loading speech model');
    await expect(status(page)).toHaveAttribute('data-kind', 'done');
    const seen: string[] = await page.evaluate(() => (window as any).__statuses);
    expect(seen.some(t => /Loading speech model/.test(t))).toBe(true);
    expect(seen.some(t => /Transcribing on your device/.test(t))).toBe(true);
    expect(seen.filter(t => /Downloading/.test(t))).toEqual([]);
  });

  test('(2) first download (not cached, after opt-in) still shows "Downloading… %"', async ({ page, baseURL }) => {
    await setup(page, baseURL!, FIXTURE, 60);
    await cachedModelEngine(page, false);
    await generateBtn(page).click();
    await page.getByRole('button', { name: 'Download model and generate subtitles' }).click();
    await expect(status(page)).toContainText('Downloading speech model… 16%');
    await expect(status(page)).toHaveAttribute('data-kind', 'done');
    const seen: string[] = await page.evaluate(() => (window as any).__statuses);
    expect(seen.filter(t => /Loading speech model/.test(t))).toEqual([]);
  });
});
